namespace WaylandFreeze {

namespace {

// Newest versions the code below knows. Screencopy 3 announces all buffer
// types before the copy (buffer_done); version 1 and 2 copy at the first
// shm buffer.
constexpr uint32_t kScreencopyVersion = 3;
constexpr uint32_t kToplevelExportVersion = 1;

// One copy request: a monitor or a window, from the compositor's offer of
// a buffer to the finished picture.
struct Frame
{
    bool isScreen = true;
    zwlr_screencopy_frame_v1 *screenFrame = nullptr;
    hyprland_toplevel_export_frame_v1 *windowFrame = nullptr;
    bool announcesBuffers = true; // gets buffer_done after the offers

    // The shm buffer the compositor offered (format, size, row length).
    bool offered = false;
    uint32_t format = 0;
    uint32_t width = 0;
    uint32_t height = 0;
    uint32_t stride = 0;
    bool yInvert = false;

    wl_shm *shm = nullptr;
    wl_buffer *buffer = nullptr;
    uchar *data = nullptr;
    size_t size = 0;

    bool finished = false;
    QImage image;

    ~Frame()
    {
        if (screenFrame)
            zwlr_screencopy_frame_v1_destroy(screenFrame);
        if (windowFrame)
            hyprland_toplevel_export_frame_v1_destroy(windowFrame);
        if (buffer)
            wl_buffer_destroy(buffer);
        if (data)
            munmap(data, size);
    }

    // The compositor offers one buffer type per event; take the first shm
    // format we can read.
    void offer(uint32_t f, uint32_t w, uint32_t h, uint32_t s)
    {
        if (offered || imageFormat(f) == QImage::Format_Invalid)
            return;
        offered = true;
        format = f;
        width = w;
        height = h;
        stride = s;
        if (!announcesBuffers)
            copy();
    }

    // All offers are in: make the buffer and ask for the copy.
    void copy()
    {
        if (finished || buffer)
            return;
        if (!offered || !makeBuffer()) {
            finished = true;
            return;
        }
        if (isScreen)
            zwlr_screencopy_frame_v1_copy(screenFrame, buffer);
        else
            hyprland_toplevel_export_frame_v1_copy(windowFrame, buffer, 1); // 1: now, not at the next damage
    }

    // Shared memory: an anonymous file the compositor writes into and we
    // read from (mmap).
    bool makeBuffer()
    {
        size = size_t(stride) * height;
        if (size == 0)
            return false;
        const int fd = memfd_create("nsl-snap-capture", MFD_CLOEXEC);
        if (fd < 0)
            return false;
        if (ftruncate(fd, off_t(size)) < 0) {
            close(fd);
            return false;
        }
        void *mapped = mmap(nullptr, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
        if (mapped == MAP_FAILED) {
            close(fd);
            return false;
        }
        data = static_cast<uchar *>(mapped);
        wl_shm_pool *pool = wl_shm_create_pool(shm, fd, int32_t(size));
        buffer = wl_shm_pool_create_buffer(pool, 0, int32_t(width), int32_t(height), int32_t(stride), format);
        // The buffer keeps the memory alive on the compositor's side.
        wl_shm_pool_destroy(pool);
        close(fd);
        return buffer != nullptr;
    }

    void ready()
    {
        image = toImage(data, int(width), int(height), int(stride), format, yInvert, !isScreen);
        finished = true;
    }

    void failed() { finished = true; }
};

// The C callbacks of both protocols, forwarding to the frame in `data`.
void screenBuffer(void *data, zwlr_screencopy_frame_v1 *, uint32_t format, uint32_t width, uint32_t height,
                  uint32_t stride)
{
    static_cast<Frame *>(data)->offer(format, width, height, stride);
}
void screenFlags(void *data, zwlr_screencopy_frame_v1 *, uint32_t flags)
{
    static_cast<Frame *>(data)->yInvert = flags & ZWLR_SCREENCOPY_FRAME_V1_FLAGS_Y_INVERT;
}
void screenReady(void *data, zwlr_screencopy_frame_v1 *, uint32_t, uint32_t, uint32_t)
{
    static_cast<Frame *>(data)->ready();
}
void screenFailed(void *data, zwlr_screencopy_frame_v1 *)
{
    static_cast<Frame *>(data)->failed();
}
void screenDamage(void *, zwlr_screencopy_frame_v1 *, uint32_t, uint32_t, uint32_t, uint32_t) {}
void screenDmabuf(void *, zwlr_screencopy_frame_v1 *, uint32_t, uint32_t, uint32_t) {}
void screenBufferDone(void *data, zwlr_screencopy_frame_v1 *)
{
    static_cast<Frame *>(data)->copy();
}

const zwlr_screencopy_frame_v1_listener kScreenListener = {
    screenBuffer, screenFlags, screenReady, screenFailed, screenDamage, screenDmabuf, screenBufferDone,
};

void windowBuffer(void *data, hyprland_toplevel_export_frame_v1 *, uint32_t format, uint32_t width, uint32_t height,
                  uint32_t stride)
{
    static_cast<Frame *>(data)->offer(format, width, height, stride);
}
void windowDamage(void *, hyprland_toplevel_export_frame_v1 *, uint32_t, uint32_t, uint32_t, uint32_t) {}
void windowFlags(void *data, hyprland_toplevel_export_frame_v1 *, uint32_t flags)
{
    static_cast<Frame *>(data)->yInvert = flags & HYPRLAND_TOPLEVEL_EXPORT_FRAME_V1_FLAGS_Y_INVERT;
}
void windowReady(void *data, hyprland_toplevel_export_frame_v1 *, uint32_t, uint32_t, uint32_t)
{
    static_cast<Frame *>(data)->ready();
}
void windowFailed(void *data, hyprland_toplevel_export_frame_v1 *)
{
    static_cast<Frame *>(data)->failed();
}
void windowDmabuf(void *, hyprland_toplevel_export_frame_v1 *, uint32_t, uint32_t, uint32_t) {}
void windowBufferDone(void *data, hyprland_toplevel_export_frame_v1 *)
{
    static_cast<Frame *>(data)->copy();
}

const hyprland_toplevel_export_frame_v1_listener kWindowListener = {
    windowBuffer, windowDamage, windowFlags, windowReady, windowFailed, windowDmabuf, windowBufferDone,
};

wl_output *outputOf(QScreen *screen)
{
    auto *native = screen ? screen->nativeInterface<QNativeInterface::QWaylandScreen>() : nullptr;
    return native ? native->output() : nullptr;
}

} // namespace

bool canCaptureScreens()
{
    WaylandConnection *connection = WaylandConnection::instance();
    return connection && connection->hasGlobal(zwlr_screencopy_manager_v1_interface.name)
           && connection->hasGlobal(wl_shm_interface.name);
}

bool canCaptureWindows()
{
    WaylandConnection *connection = WaylandConnection::instance();
    return connection && connection->hasGlobal(hyprland_toplevel_export_manager_v1_interface.name);
}

Pictures capture(const QList<QScreen *> &screens, const QList<uint32_t> &windows, int timeoutMs)
{
    Pictures pictures;
    pictures.screens.resize(screens.size());
    pictures.windows.resize(windows.size());
    WaylandConnection *connection = WaylandConnection::instance();
    if (!connection)
        return pictures;

    // The managers are bound for this capture only and released at the end.
    auto *shm = static_cast<wl_shm *>(connection->bind(&wl_shm_interface, 1));
    uint32_t screencopyVersion = 0;
    auto *screencopy = static_cast<zwlr_screencopy_manager_v1 *>(
        connection->bind(&zwlr_screencopy_manager_v1_interface, kScreencopyVersion, &screencopyVersion));
    auto *toplevelExport = windows.isEmpty()
        ? nullptr
        : static_cast<hyprland_toplevel_export_manager_v1 *>(
              connection->bind(&hyprland_toplevel_export_manager_v1_interface, kToplevelExportVersion));

    // Frames hold pointers into themselves for the callbacks: keep them
    // at fixed addresses.
    std::vector<std::unique_ptr<Frame>> screenFrames;
    std::vector<std::unique_ptr<Frame>> windowFrames;
    if (shm) {
        for (QScreen *screen : screens) {
            auto frame = std::make_unique<Frame>();
            frame->shm = shm;
            wl_output *output = outputOf(screen);
            if (screencopy && output) {
                frame->announcesBuffers = screencopyVersion >= 3;
                frame->screenFrame = zwlr_screencopy_manager_v1_capture_output(screencopy, 0, output); // 0: no pointer
                zwlr_screencopy_frame_v1_add_listener(frame->screenFrame, &kScreenListener, frame.get());
            } else {
                frame->finished = true;
            }
            screenFrames.push_back(std::move(frame));
        }
        for (uint32_t handle : windows) {
            auto frame = std::make_unique<Frame>();
            frame->shm = shm;
            frame->isScreen = false;
            if (toplevelExport) {
                frame->windowFrame = hyprland_toplevel_export_manager_v1_capture_toplevel(toplevelExport, 0, handle);
                hyprland_toplevel_export_frame_v1_add_listener(frame->windowFrame, &kWindowListener, frame.get());
            } else {
                frame->finished = true;
            }
            windowFrames.push_back(std::move(frame));
        }

        const auto allFinished = [&] {
            for (const auto &frame : screenFrames) {
                if (!frame->finished)
                    return false;
            }
            for (const auto &frame : windowFrames) {
                if (!frame->finished)
                    return false;
            }
            return true;
        };
        connection->dispatchUntil(allFinished, timeoutMs);
    }

    for (size_t i = 0; i < screenFrames.size(); ++i)
        pictures.screens[qsizetype(i)] = screenFrames[i]->image;
    for (size_t i = 0; i < windowFrames.size(); ++i)
        pictures.windows[qsizetype(i)] = windowFrames[i]->image;

    screenFrames.clear();
    windowFrames.clear();
    if (toplevelExport)
        hyprland_toplevel_export_manager_v1_destroy(toplevelExport);
    if (screencopy)
        zwlr_screencopy_manager_v1_destroy(screencopy);
    if (shm)
        wl_shm_destroy(shm);
    // Let the compositor see the destroy requests now, not at Qt's next flush.
    connection->roundtrip();
    return pictures;
}

QImage::Format imageFormat(uint32_t shmFormat)
{
    switch (shmFormat) {
    case WL_SHM_FORMAT_ARGB8888: return QImage::Format_ARGB32_Premultiplied;
    case WL_SHM_FORMAT_XRGB8888: return QImage::Format_RGB32;
    case WL_SHM_FORMAT_ABGR8888: return QImage::Format_RGBA8888_Premultiplied;
    case WL_SHM_FORMAT_XBGR8888: return QImage::Format_RGBX8888;
    case WL_SHM_FORMAT_ARGB2101010: return QImage::Format_A2RGB30_Premultiplied;
    case WL_SHM_FORMAT_XRGB2101010: return QImage::Format_RGB30;
    case WL_SHM_FORMAT_ABGR2101010: return QImage::Format_A2BGR30_Premultiplied;
    case WL_SHM_FORMAT_XBGR2101010: return QImage::Format_BGR30;
    default: return QImage::Format_Invalid;
    }
}

QImage toImage(const uchar *data, int width, int height, int stride, uint32_t shmFormat, bool yInvert, bool keepAlpha)
{
    const QImage::Format format = imageFormat(shmFormat);
    if (!data || width <= 0 || height <= 0 || format == QImage::Format_Invalid)
        return {};
    // Wraps the shared memory without copying; convertToFormat() copies.
    const QImage wrapped(data, width, height, stride, format);
    QImage image = wrapped.convertToFormat(keepAlpha ? QImage::Format_ARGB32 : QImage::Format_RGB32);
    if (image.constBits() == wrapped.constBits())
        image = image.copy(); // same format: detach from the shared memory
    if (yInvert)
        image = image.transformed(QTransform::fromScale(1, -1));
    return image;
}

} // namespace WaylandFreeze
